const test = require('node:test');
const assert = require('node:assert/strict');
const { createThumbnailCache } = require('../thumbnails.cjs');
test('overwrite preserves first insertion position', () => {
  const c = createThumbnailCache(2);
  c.put('a','old'); c.put('b','B'); c.put('a','new');
  assert.deepEqual(c.keys(), ['a','b']);
  assert.equal(c.get('a'), 'new');
  c.put('c','C');
  assert.deepEqual(c.keys(), ['b','c']);
  assert.equal(c.get('a'), undefined);
  assert.equal(c.get('b'), 'B');
});
test('reads do not reorder and reinsertion is new', () => {
  const c = createThumbnailCache(2);
  c.put('x',1); c.put('y',2); c.get('x'); c.put('z',3);
  assert.deepEqual(c.keys(), ['y','z']);
  c.put('x',4);
  assert.deepEqual(c.keys(), ['z','x']);
  const keys = c.keys(); keys.pop();
  assert.deepEqual(c.keys(), ['z','x']);
  const one = createThumbnailCache(1);
  one.put('a',1); one.put('a',2); one.put('b',3);
  assert.deepEqual(one.keys(), ['b']);
});

